package shiori

/** Interface text in French, English, Japanese and Traditional Chinese. Every key exists in all four (a test checks it). */
object I18n {
    val LOCALES = listOf("fr", "en", "ja", "zh-Hant")
    val NAMES = mapOf("fr" to "Français", "en" to "English", "ja" to "日本語", "zh-Hant" to "繁體中文")

    fun t(lang: String, key: String, vararg args: Any): String {
        val s = (TEXT[lang] ?: TEXT.getValue("en"))[key] ?: TEXT.getValue("en")[key] ?: key
        var out = s
        args.forEachIndexed { i, a -> out = out.replace("{$i}", a.toString()) }
        return out
    }

    fun pick(acceptLanguage: String?): String {
        val tags = acceptLanguage.orEmpty().split(',').map { it.substringBefore(';').trim().lowercase() }
        for (tag in tags) {
            when {
                tag.startsWith("zh") && (tag.contains("hant") || tag.endsWith("tw") || tag.endsWith("hk")) -> return "zh-Hant"
                tag.startsWith("zh") -> return "zh-Hant"
                tag.startsWith("ja") -> return "ja"
                tag.startsWith("fr") -> return "fr"
                tag.startsWith("en") -> return "en"
            }
        }
        return "en"
    }

